    fn cursor_bounds(&self, cx: &App) -> Option<Bounds<Pixels>> {
        let editor = self.editor.read(cx);
        let (cursor, line_height) = editor.cursor_layout()?;
        Some(Bounds::new(
            cursor.origin + editor.scroll_offset(),
            size(cursor.size.width, line_height),
        ))
    }
